import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        FastReader r = new FastReader();
        int n = r.nextInt();
        final long off = 1_000_000_000L;
        // Key sorts by (start, end), both shifted to be non-negative.
        long[] key = new long[n];
        for (int i = 0; i < n; i++) {
            long a = r.nextLong() + off, b = r.nextLong() + off;
            key[i] = (a << 31) | b;
        }
        Arrays.sort(key);
        long[] os = new long[n], oe = new long[n];
        int m = 0;
        for (long kv : key) {
            long a = (kv >> 31) - off, b = (kv & ((1L << 31) - 1)) - off;
            if (m > 0 && a <= oe[m - 1]) oe[m - 1] = Math.max(oe[m - 1], b);
            else { os[m] = a; oe[m] = b; m++; }
        }
        StringBuilder sb = new StringBuilder();
        sb.append(m).append('\n');
        for (int i = 0; i < m; i++) sb.append(os[i]).append(' ').append(oe[i]).append('\n');
        System.out.print(sb);
    }
}

final class FastReader {
    private final java.io.InputStream in = System.in;
    private final byte[] buf = new byte[1 << 16];
    private int len = 0, ptr = 0;

    private int read() throws java.io.IOException {
        if (ptr == len) {
            len = in.read(buf, 0, buf.length);
            ptr = 0;
            if (len <= 0) { len = 0; return -1; }
        }
        return buf[ptr++];
    }

    String next() throws java.io.IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') { sb.append((char) c); c = read(); }
        return sb.toString();
    }

    long nextLong() throws java.io.IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + (c - '0'); c = read(); }
        return neg ? -r : r;
    }

    int nextInt() throws java.io.IOException { return (int) nextLong(); }
}

package main

import (
	"bufio"
	"cmp"
	"os"
	"slices"
	"strconv"
)

func main() {
	n := readInt()
	v := make([][2]int, n)
	for i := range v {
		v[i] = [2]int{readInt(), readInt()}
	}
	slices.SortFunc(v, func(a, b [2]int) int {
		if a[0] != b[0] {
			return cmp.Compare(a[0], b[0])
		}
		return cmp.Compare(a[1], b[1])
	})
	var out [][2]int
	for _, p := range v {
		if len(out) > 0 && p[0] <= out[len(out)-1][1] {
			out[len(out)-1][1] = max(out[len(out)-1][1], p[1])
		} else {
			out = append(out, p)
		}
	}
	buf := strconv.AppendInt(nil, int64(len(out)), 10)
	buf = append(buf, '\n')
	for _, p := range out {
		buf = strconv.AppendInt(buf, int64(p[0]), 10)
		buf = append(buf, ' ')
		buf = strconv.AppendInt(buf, int64(p[1]), 10)
		buf = append(buf, '\n')
	}
	os.Stdout.Write(buf)
}

var reader = bufio.NewReaderSize(os.Stdin, 1<<16)

func readToken() string {
	b, err := reader.ReadByte()
	for err == nil && b <= ' ' {
		b, err = reader.ReadByte()
	}
	var buf []byte
	for err == nil && b > ' ' {
		buf = append(buf, b)
		b, err = reader.ReadByte()
	}
	return string(buf)
}

func readInt() int {
	b, err := reader.ReadByte()
	for err == nil && b <= ' ' {
		b, err = reader.ReadByte()
	}
	neg := false
	if b == '-' {
		neg = true
		b, err = reader.ReadByte()
	}
	r := 0
	for err == nil && b >= '0' && b <= '9' {
		r = r*10 + int(b-'0')
		b, err = reader.ReadByte()
	}
	if neg {
		return -r
	}
	return r
}
